    {"name": "smart_tracker", "description": "RASTREADOR INTELIGENTE DE PANTALLA AVANZADO. Usa MULTIPLES ESTRATEGIAS: OCR local (texto), UI Automation (Windows nativo), y Visión IA. Acciones: find (ubicar elemento), scan (estructura completa de pantalla + OCR), click (ubicar + cliquear), right_click, double_click, ocr (extraer todo el texto de la pantalla), ui_tree (árbol de elementos UI), window (info de ventana activa), click_at (clic en coordenadas X,Y), describe (descripción completa con IA). USAR SIEMPRE que el usuario pregunte 'dónde está X', 'buscá X en la pantalla', 'encuentra X', 'leé lo que dice la pantalla', 'qué texto hay'.", "parameters": {"type": "object", "properties": {"action": {"type": "string", "description": "find | scan | click | right_click | double_click | describe | ocr | ui_tree | window | click_at (default: find)."}, "target": {"type": "string", "description": "Descripción del elemento o texto a buscar (botón, campo, ícono, texto)."}, "element": {"type": "string", "description": "Sinónimo de target."}, "description": {"type": "string", "description": "Sinónimo de target."}, "click": {"type": "string", "description": "true | false - hace clic automático al encontrar (default: false)."}, "strategy": {"type": "string", "description": "auto (prueba OCR→UI→IA, default) | ocr (solo OCR local) | ui (solo UI Automation). Solo para action=find."}, "x": {"type": "integer", "description": "Coordenada X para click_at."}, "y": {"type": "integer", "description": "Coordenada Y para click_at."}}, "required": []}},
